<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute } from 'vue-router'
import { api, apiPage, mutation, uploadAttachment } from '../api/client'
import RunPanel from '../components/RunPanel.vue'
type Goal={goal_version_id:string;role_direction:string}
type Evidence={kind:string;description:string;claimed_skills:string[];attachment_ids:string[];evidence_id:string;evidence_version_id:string;title:string;verification_scope:string;version:number}
type Criterion={dimension:'artifact'|'explanation'|'transfer';scenario:string;expected_behavior:string;pass_rule:string;fail_rule:string;unknown_rule:string;critical:boolean;allowed_methods:string[];required_artifact_types:string[];limitations:string[]}
type Objective={planning_basis?:{planning_context_id:string;selected_alternatives:unknown[]};objective_id:string;objective_version_id:string;title:string;target_behavior:string;scope:string;origin:string;deliverables:string[];prerequisite_objective_ids:string[];effort_hours:{min:number;max:number}|null;criteria:Criterion[];criterion_version_ids:string[];version:number;goal_version_id:string}
type Plan={eligibility_checks?:{field:string;status:string}[];version_no?:number;plan_id:string;plan_version_id:string;version:number;kind:string;goal_version_id:string;active_plan_version_id:string|null;objective_version_ids:string[];objectives:Objective[];warnings?:string[];user_constraints?:{available_hours:number|null;notes?:string};deferred?:string[]}
const goals=ref<Goal[]>([]), goalId=ref(''), evidence=ref<Evidence[]>([]), objectives=ref<Objective[]>([])
const reports=ref<{market_report_id:string;created_at:string}[]>([]), reportId=ref(''), evidenceIds=ref<string[]>([])
const plans=ref<Plan[]>([]), plan=ref<Plan|null>(null), selected=ref<string[]>([]), runId=ref(''), busy=ref(false)
const materialSections=ref<string[]>([]), incomingReport=ref('')
const availableHours=ref<number|null>(null), evidenceFile=ref<File|null>(null), uploadedId=ref('')
const evidenceForm=reactive({kind:'readme',title:'',description:'',claimed_skills:''})
const write=mutation(), uploadKey=ref(crypto.randomUUID()), editingEvidence=ref<Evidence|null>(null)
const alignment=ref<{alignments:{category:string;reason:string;unknown_questions:string[]}[]}|null>(null)
const objectiveDialog=ref(false), editing=ref<Objective|null>(null), editingInPlan=ref(false), savingObjective=ref(false), savingPlan=ref(false)
const budgetNotes=ref('')
const budgetDirty=computed(()=>!!plan.value&&(availableHours.value!==(plan.value.user_constraints?.available_hours??null)||budgetNotes.value!==(plan.value.user_constraints?.notes??'')))
const selectionDirty=computed(()=>!!plan.value&&JSON.stringify(selected.value)!==JSON.stringify(plan.value.objective_version_ids))
function selectPlan(id:string){const found=plans.value.find(p=>p.plan_id===id);if(found)showPlan(found)}
const planCards=computed(()=>selected.value.map(id=>plan.value?.objectives.find(o=>o.objective_version_id===id)??objectives.value.find(o=>o.objective_version_id===id)).filter((o):o is Objective=>!!o))
const objectiveForm=reactive({title:'',target_behavior:'',scope:'',deliverables:'',prerequisite_objective_ids:[] as string[],estimate:false,min:1,max:4,criteria:[] as Criterion[],scope_confirmed:false})
function blankCriterion():Criterion{return {dimension:'artifact',scenario:'',expected_behavior:'',pass_rule:'',fail_rule:'观察不符合预期',unknown_rule:'材料或环境不完整',critical:true,allowed_methods:['human_review','user_reported'],required_artifact_types:['execution_record'],limitations:[]}}
async function all<T>(path:string):Promise<T[]>{const data:T[]=[];let cursor:string|null=null;do{const page:{data:T[];next_cursor?:string|null}=await apiPage<T>(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+cursor:''));data.push(...page.data);cursor=page.next_cursor??null}while(cursor);return data}
async function load(){try{goals.value=await all<Goal>('/career-goals');if(!goalId.value)goalId.value=goals.value[0]?.goal_version_id??'';evidence.value=await all<Evidence>('/evidence');objectives.value=await all<Objective>('/learning-objectives');plans.value=await all<Plan>('/plans');await loadReports()}catch(e){ElMessage.error(String(e))}}
async function loadReports(){reports.value=await all('/market-reports?goal_version_id='+goalId.value);reportId.value=reports.value.some(r=>r.market_report_id===reportId.value)?reportId.value:reports.value.some(r=>r.market_report_id===incomingReport.value)?incomingReport.value:reports.value[0]?.market_report_id??''}
async function saveEvidence(){busy.value=true;try{if(evidenceFile.value&&!uploadedId.value){const result=await uploadAttachment(evidenceFile.value,'personal_evidence',uploadKey.value);uploadedId.value=result.attachment_id}
await write(editingEvidence.value?'/evidence/'+editingEvidence.value.evidence_id+'/versions':'/evidence','POST',{...(editingEvidence.value?{expected_version:editingEvidence.value.version,change_reason:'用户更新个人材料'}:{}),kind:evidenceForm.kind,title:evidenceForm.title,description:evidenceForm.description,claimed_skills:evidenceForm.claimed_skills.split(/[,，]/).map(x=>x.trim()).filter(Boolean),attachment_ids:uploadedId.value?[uploadedId.value]:(editingEvidence.value?.attachment_ids??[]),declared_verification:uploadedId.value?'attached_material':'self_reported',environment:{}});Object.assign(evidenceForm,{title:'',description:'',claimed_skills:''});evidenceFile.value=null;editingEvidence.value=null;uploadedId.value='';uploadKey.value=crypto.randomUUID();await load();ElMessage.success('已保存个人材料；未认定运行通过或能力掌握。')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
function editEvidence(row:Evidence){editingEvidence.value=row;Object.assign(evidenceForm,{kind:row.kind,title:row.title,description:row.description,claimed_skills:row.claimed_skills.join(',')});uploadedId.value='';evidenceFile.value=null}
function cancelEvidence(){editingEvidence.value=null;Object.assign(evidenceForm,{kind:'readme',title:'',description:'',claimed_skills:''});uploadedId.value='';evidenceFile.value=null}
async function deleteEvidence(row:Evidence){try{await ElMessageBox.confirm('撤销后关联材料和历史衍生正文不可读取。确定删除这份个人材料？','删除个人材料',{type:'warning'});await write('/evidence/'+row.evidence_id,'DELETE',{expected_version:row.version});await load();ElMessage.success('材料读取已撤销。')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}}
async function beginAlignment(){try{const run=await write<{run_id:string}>('/alignment-runs','POST',{goal_version_id:goalId.value,market_report_id:reportId.value,personal_evidence_version_ids:evidenceIds.value,user_constraints:{available_hours:availableHours.value}});runId.value=run.run_id}catch(e){ElMessage.error(String(e))}}
async function progress(){try{const run=await api<{output_refs:{plan_id?:string;alignment_report_id?:string}[]}>(`/runs/${runId.value}`);const result=run.output_refs.find(x=>x.plan_id);if(result?.alignment_report_id)alignment.value=await api('/alignment-reports/'+result.alignment_report_id);if(result?.plan_id){showPlan(await api<Plan>('/plans/'+result.plan_id));await load()}}catch(e){ElMessage.error(String(e))}}
function showPlan(row:Plan){plan.value=row;goalId.value=row.goal_version_id;selected.value=[...row.objective_version_ids];availableHours.value=row.user_constraints?.available_hours??null;budgetNotes.value=row.user_constraints?.notes??'';void loadReports()}
async function adopt(){if(!plan.value)return;try{const result=await write<{active_plan_version_id:string}>(`/plans/${plan.value.plan_id}/adopt`,'POST',{expected_version:plan.value.version,plan_version_id:plan.value.plan_version_id,expected_goal_version_id:plan.value.goal_version_id,selected_objective_version_ids:selected.value});plan.value=await api<Plan>(`/plans/${plan.value.plan_id}/versions/${result.active_plan_version_id}`);await load();ElMessage.success('已采纳计划；后续修改会保存为新的草稿。')}catch(e){ElMessage.error(String(e))}}
async function saveDraft(){if(!plan.value)return;savingPlan.value=true;try{const saved=await write<Plan>(`/plans/${plan.value.plan_id}/versions`,'POST',{expected_version:plan.value.version,base_plan_version_id:plan.value.plan_version_id,objective_version_ids:selected.value,adjustment_reason:'用户在学习计划中调整目标、顺序与时间预算',user_constraints:{available_hours:availableHours.value,notes:budgetNotes.value},deferred:plan.value.deferred??[]});showPlan(saved);await load();ElMessage.success('学习计划草稿已保存。')}catch(e){ElMessage.error(String(e))}finally{savingPlan.value=false}}
function openObjective(row:Objective|null,inPlan=false){if(inPlan&&(selectionDirty.value||budgetDirty.value)){ElMessage.warning('请先保存目标选择、顺序与工时，再编辑目标内容。');return}editingInPlan.value=inPlan;editing.value=row;Object.assign(objectiveForm,{title:row?.title??'',target_behavior:row?.target_behavior??'',scope:row?.scope??'',deliverables:row?.deliverables.join('\n')??'',prerequisite_objective_ids:row?.prerequisite_objective_ids??[],estimate:!!row?.effort_hours,min:row?.effort_hours?.min??1,max:row?.effort_hours?.max??4,criteria:row?(JSON.parse(JSON.stringify(row.criteria)) as Criterion[]).map(c=>({dimension:c.dimension,scenario:c.scenario,expected_behavior:c.expected_behavior,pass_rule:c.pass_rule,fail_rule:c.fail_rule,unknown_rule:c.unknown_rule,critical:c.critical,allowed_methods:c.allowed_methods,required_artifact_types:c.required_artifact_types,limitations:c.limitations})):[blankCriterion()],scope_confirmed:false});objectiveDialog.value=true}
async function saveObjective(){savingObjective.value=true;try{const body={goal_version_id:editingInPlan.value&&plan.value?plan.value.goal_version_id:goalId.value,title:objectiveForm.title,target_behavior:objectiveForm.target_behavior,scope:objectiveForm.scope,deliverables:objectiveForm.deliverables.split('\n').filter(Boolean),prerequisite_objective_ids:objectiveForm.prerequisite_objective_ids,effort_hours:objectiveForm.estimate?{min:objectiveForm.min,max:objectiveForm.max,is_estimate:true}:null,criteria:objectiveForm.criteria,scope_confirmed:objectiveForm.scope_confirmed,...(editing.value?{expected_version:editing.value.version,change_reason:'用户在学习计划中调整目标内容与验收条件'}:{})};
if(editingInPlan.value&&editing.value&&plan.value){const saved=await write<Plan>(`/plans/${plan.value.plan_id}/objectives/${editing.value.objective_id}/versions`,'POST',{expected_plan_version:plan.value.version,base_plan_version_id:plan.value.plan_version_id,objective:body});showPlan(saved)}else{await write(editing.value?`/learning-objectives/${editing.value.objective_id}/versions`:'/learning-objectives','POST',body)}
objectiveDialog.value=false;await load();ElMessage.success(editingInPlan.value?'目标和学习计划已同时保存为新草稿。':'学习目标已保存，可从下方候选目标加入计划。')}catch(e){ElMessage.error(String(e))}finally{savingObjective.value=false}}
function move(index:number,delta:number){const next=index+delta;if(next<0||next>=selected.value.length)return;const a=selected.value[index]!,b=selected.value[next]!;selected.value[index]=b;selected.value[next]=a}
const route=useRoute()
onMounted(async()=>{await load();try{if(typeof route.query.report==='string'){const received=await api<{goal_version_id:string;market_report_id:string}>('/market-reports/'+encodeURIComponent(route.query.report));incomingReport.value=received.market_report_id;goalId.value=received.goal_version_id;const existing=plans.value.find(p=>p.goal_version_id===goalId.value&&p.kind==='draft')??plans.value.find(p=>p.goal_version_id===goalId.value);if(existing)showPlan(existing);reportId.value=received.market_report_id;await loadReports();materialSections.value=['materials']}else if(typeof route.query.plan==='string'){showPlan(await api<Plan>('/plans/'+encodeURIComponent(route.query.plan)))}else{const target=typeof route.query.objective==='string'?plans.value.find(p=>p.objective_version_ids.includes(route.query.objective as string)):null;const initial=target??plans.value.find(p=>p.kind==='draft')??plans.value[0];if(initial)showPlan(initial)}}catch(e){ElMessage.error(String(e))}})
</script>
<template>
<section class="page-heading"><div><span class="eyebrow">目标 → 学习内容 → 计划编辑</span><h1>证据与学习计划</h1><p>直接在已有计划中调整学习目标、交付物、工时和验收条件。</p></div><el-button @click="load">刷新列表</el-button></section>
<el-alert title="计划修改会保留旧版本，已采纳计划的修改先保存为新草稿；学习内容不自动认定为已掌握。" :closable="false"/>
<section class="table-card plan-panel"><h2>已有学习计划</h2><el-select :model-value="plan?.plan_id" style="width:100%" placeholder="选择要编辑的计划" @change="selectPlan"><el-option v-for="p in plans" :key="p.plan_id" :value="p.plan_id" :label="(goals.find(g=>g.goal_version_id===p.goal_version_id)?.role_direction??'历史职业目标')+' · v'+p.version+' · '+(p.kind==='draft'?'草稿':'已采纳')"/></el-select><p v-if="!plans.length" class="muted">暂无计划，可展开下方“材料与计划生成”创建。</p></section>
<section v-if="plan" class="table-card plan-panel"><div class="card-top"><h2>{{plan.kind==='draft'?'编辑计划草稿':'基于采纳版本编辑'}} · v{{plan.version_no??plan.version}}</h2><el-tag>{{plan.objectives.length}} 个已保存目标</el-tag></div>
<p v-for="check in plan.eligibility_checks" :key="check.field">资格条件：{{check.field}} · {{check.status}}（待本人确认）</p><el-form label-position="top"><el-form-item label="本计划可用总工时（未确定可留空）"><el-input-number v-model="availableHours" :min="1" :max="10000"/></el-form-item><el-form-item label="时间安排与备注"><el-input v-model="budgetNotes" type="textarea" :rows="2"/></el-form-item></el-form>
<el-alert v-if="selectionDirty" title="目标选择或顺序尚未保存，请先保存草稿，再编辑具体目标。" type="warning" :closable="false"/>
<article v-for="(o,n) in planCards" :key="o.objective_version_id" class="plan-objective"><div class="card-top"><h3>{{n+1}}. {{o.title}}</h3><el-button type="primary" plain :disabled="selectionDirty" @click="openObjective(o,true)">编辑目标</el-button></div><p>{{o.target_behavior}}</p><p class="muted">范围：{{o.scope}}</p><el-collapse v-if="o.planning_basis"><el-collapse-item title="查看岗位依据与二选一分支"><p>冻结上下文：{{o.planning_basis.planning_context_id}}</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{JSON.stringify(o.planning_basis.selected_alternatives,null,2)}}</pre></el-collapse-item></el-collapse><p>交付物：{{o.deliverables.join('、')}}</p><p>预计工时：{{o.effort_hours?o.effort_hours.min+'—'+o.effort_hours.max+' 小时':'待确定'}} · 先修：{{o.prerequisite_objective_ids.map(id=>objectives.find(x=>x.objective_id===id)?.title??'历史目标').join('、')||'无'}}</p><el-collapse><el-collapse-item title="查看完整验收条件"><div v-for="(c,i) in o.criteria" :key="i"><h4>{{c.dimension}} · {{c.scenario}}</h4><p>预期：{{c.expected_behavior}}</p><p>通过：{{c.pass_rule}}</p><p>失败：{{c.fail_rule}}</p><p>未知：{{c.unknown_rule}}</p></div></el-collapse-item></el-collapse><p><el-button :disabled="n===0" @click="move(n,-1)">上移</el-button><el-button :disabled="n===planCards.length-1" @click="move(n,1)">下移</el-button><el-button type="danger" plain @click="selected=selected.filter(id=>id!==o.objective_version_id)">从本草稿移除</el-button></p></article>
<h3>加入或移除学习目标</h3><el-select v-model="selected" multiple filterable style="width:100%" placeholder="选择同一职业目标下的学习目标"><el-option v-for="o in objectives.filter(o=>o.goal_version_id===plan?.goal_version_id)" :key="o.objective_version_id" :value="o.objective_version_id" :label="o.title+' · v'+o.version"/></el-select><p><el-button @click="openObjective(null)">创建候选学习目标</el-button></p><p class="muted">移除只影响新计划草稿；先修目标必须保留且排在依赖目标之前。</p><el-button type="primary" :loading="savingPlan" :disabled="!selected.length" @click="saveDraft">保存计划草稿</el-button><el-button :disabled="plan.kind!=='draft'||!selected.length||selectionDirty||budgetDirty" @click="adopt">核对并采纳计划</el-button><p>参考代码、阅读进度和笔记仍在“项目与代码学习”中管理。</p></section>
<el-alert v-if="incomingReport" title="已接收岗位分析报告。请核对个人材料并生成对齐草案；已有计划保留，修改后再保存新草稿。" type="success" :closable="false"/><el-collapse v-model="materialSections" class="plan-panel"><el-collapse-item title="材料与计划生成" name="materials"><section class="table-card plan-panel"><h2>个人材料</h2><el-form label-position="top"><el-form-item label="材料标题"><el-input v-model="evidenceForm.title"/></el-form-item><el-form-item label="描述、本人贡献和未知范围"><el-input v-model="evidenceForm.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="自述关联技能（逗号分隔）"><el-input v-model="evidenceForm.claimed_skills"/></el-form-item><el-form-item label="文本附件（可选）"><input type="file" accept=".txt,.md,.json,.log,.py,.xml" @change="evidenceFile=($event.target as HTMLInputElement).files?.[0]??null;uploadedId=''"/></el-form-item><el-button type="primary" :loading="busy" @click="saveEvidence">{{editingEvidence?'保存材料新版本':'保存材料'}}</el-button><el-button v-if="editingEvidence" @click="cancelEvidence">取消编辑</el-button></el-form><el-table :data="evidence.filter(e=>e.kind!=='mock_research_summary')"><el-table-column prop="title" label="材料"/><el-table-column prop="version" label="版本"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="editEvidence(row)">编辑材料</el-button><el-button link type="danger" @click="deleteEvidence(row)">删除材料</el-button></template></el-table-column></el-table></section>
<section class="table-card plan-panel"><h2>生成对齐草案</h2><el-form label-position="top"><el-form-item label="职业目标版本"><el-select v-model="goalId" @change="loadReports"><el-option v-for="g in goals" :key="g.goal_version_id" :label="g.role_direction" :value="g.goal_version_id"/></el-select></el-form-item><el-form-item label="岗位报告"><el-select v-model="reportId"><el-option v-for="r in reports" :key="r.market_report_id" :label="new Date(r.created_at).toLocaleString()" :value="r.market_report_id"/></el-select></el-form-item><el-form-item label="个人材料的具体版本"><el-select v-model="evidenceIds" multiple><el-option v-for="e in evidence.filter(e=>e.kind!=='mock_research_summary')" :key="e.evidence_version_id" :label="e.title+' · v'+e.version" :value="e.evidence_version_id"/></el-select></el-form-item><el-form-item label="本次可用总工时（未确定可留空）"><el-input-number v-model="availableHours" :min="1"/></el-form-item><el-button :disabled="!reportId" type="primary" @click="beginAlignment">生成离线草案</el-button><el-button @click="openObjective(null)">直接创建学习目标</el-button></el-form></section></el-collapse-item></el-collapse>
<RunPanel v-if="runId" :key="runId" :run-id="runId" @changed="progress"/>
<section v-if="alignment" class="table-card plan-panel"><h2>证据对齐结果</h2><div v-for="(item,n) in alignment.alignments" :key="n"><strong>{{item.category==='unknown'?'未知':item.category}}</strong><p>{{item.reason}}</p><p v-for="q in item.unknown_questions" :key="q">补证问题：{{q}}</p></div></section>
<el-dialog v-model="objectiveDialog" title="目标与完整验收条件" width="min(860px,96vw)"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="objectiveForm.title"/></el-form-item><el-form-item label="要观察到的行为"><el-input v-model="objectiveForm.target_behavior" type="textarea"/></el-form-item><el-form-item label="范围和环境边界"><el-input v-model="objectiveForm.scope" type="textarea"/></el-form-item><el-form-item label="交付物（每行一项）"><el-input v-model="objectiveForm.deliverables" type="textarea"/></el-form-item><el-form-item label="先修目标"><el-select v-model="objectiveForm.prerequisite_objective_ids" multiple><el-option v-for="o in objectives.filter(o=>o.objective_id!==editing?.objective_id&&o.goal_version_id===goalId)" :key="o.objective_id" :label="o.title" :value="o.objective_id"/></el-select></el-form-item><el-checkbox v-model="objectiveForm.estimate">提供估计工时区间</el-checkbox><div v-if="objectiveForm.estimate"><el-input-number v-model="objectiveForm.min" :min="0"/> 至 <el-input-number v-model="objectiveForm.max" :min="1"/> 小时（估计）</div><div v-for="(c,n) in objectiveForm.criteria" :key="n" style="border-top:1px solid #ddd;margin-top:20px;padding-top:15px"><h3>条件 {{n+1}}</h3><el-select v-model="c.dimension"><el-option label="成果表现" value="artifact"/><el-option label="解释证据" value="explanation"/><el-option label="迁移证据" value="transfer"/></el-select><el-form-item label="场景"><el-input v-model="c.scenario"/></el-form-item><el-form-item label="可观察行为"><el-input v-model="c.expected_behavior"/></el-form-item><el-form-item label="通过规则"><el-input v-model="c.pass_rule"/></el-form-item><el-form-item label="失败规则"><el-input v-model="c.fail_rule"/></el-form-item><el-form-item label="未知规则"><el-input v-model="c.unknown_rule"/></el-form-item><el-form-item label="所需材料"><el-select v-model="c.required_artifact_types" multiple allow-create filterable><el-option v-for="a in ['execution_record','explanation_answer','transfer_note','code_artifact']" :key="a" :label="a" :value="a"/></el-select></el-form-item><el-form-item label="允许的检查方法"><el-checkbox-group v-model="c.allowed_methods"><el-checkbox value="model_review">材料辅助审阅</el-checkbox><el-checkbox value="user_reported">用户报告</el-checkbox><el-checkbox value="human_review">本人自验</el-checkbox></el-checkbox-group></el-form-item><el-checkbox v-model="c.critical">关键条件</el-checkbox><el-button link type="danger" @click="objectiveForm.criteria.splice(n,1)">移除此草案条件</el-button></div><el-button @click="objectiveForm.criteria.push(blankCriterion())">添加条件</el-button><p><el-checkbox v-model="objectiveForm.scope_confirmed">已核对本次范围、交付物和完整条件；旧版本保留；在计划内编辑时同步保存新草稿。</el-checkbox></p></el-form><template #footer><el-button type="primary" :disabled="!objectiveForm.scope_confirmed" :loading="savingObjective" @click="saveObjective">{{editingInPlan?'保存目标并更新计划':'保存学习目标'}}</el-button></template></el-dialog>

</template>
<style scoped>
.plan-panel{padding:24px;margin:20px 0}.plan-panel h2{font-size:20px;margin:5px 0 20px}.plan-objective{padding:22px 0;border-top:1px solid #e4ebe7}.plan-objective h3{font-size:17px;margin:8px 0;line-height:1.7}.plan-objective p{font-size:14px;line-height:1.9}.plan-objective .card-top{gap:16px;align-items:flex-start}@media(max-width:720px){.plan-panel{padding:18px}.plan-objective .card-top{display:block}}
</style>
